i_tmp=i;
while((n_temp=n3.exec(result))!=null){
n_sub=n_temp[1];
if((n_sub.match(/span/))!=null){n_sub=n_sub.match(/span>(.+)<\/span><spa/)[1];n_sub='🔒'+n_sub;}
